 all_sources_blnd ,  TRIM(AC.FORM_H_SCHOOL_NAME)   as   form_h_school_name ,  TRIM(AC.FORM_H_SCHOOL_ADDR)   as   form_h_school_addr ,  TRIM(AC.FORM_H_SCHOOL_CITY)   as   form_h_school_city ,  TRIM(AC.FORM_H_SCHOOL_STATEPROV)   as   form_h_school_stateprov ,  TRIM(AC.FORM_H_SCHOOL_POST_CODE)   as   form_h_school_post_code ,  TRIM(AC.FORM_H_SCHOOL_COUNTRY)   as   form_h_school_country ,  TRIM(AC.FORM_H_SCHOOL_GRAD_YEAR)   as   form_h_school_grad_year ,  TRIM(AC.FORM_ENTRY_YEAR)   as   form_entry_year ,  TRIM(Con.current_grade_level)   as   h_school_grade_level_calc ,  TRIM(Con.grad_year)   as   h_school_grad_year_calc ,  TRIM(max_values.sat_max)   as   max_sat_score_rng_calc ,  TRIM(max_values.act_max)   as   max_act_score_rng_calc ,  TRIM(max_values.psat_max)   as   max_psat_score_rng_calc ,  TRIM(max_values.preact_max)   as   max_preact_score_rng_calc ,  null   as   fafsa_submit_date_partner ,  TRIM(Con.contact_rand)   as   random_number ,  TRIM(AC.FORM_BOT_HONEYPOT)   as   form_bot_honeypot ,  case when AC.ACS_REPLICATION_DATE IS NOT NULL then CONCAT(LEFT(REPLACE(TRIM(AC.ACS_REPLICATION_DATE), ' ', 'T'), 19), '+00:00') else null end   as   acs_replication_date ,  TRIM(xwalk.print_display_id)   as   print_display_id ,  TRIM(PD.PANTO_SCHOOL_GUID)   as   es_partner_id ,  TRIM(AC.FORM_ACADEMIC_FIELD_INTRS)   as   Form_Academic_Field_Intrs ,  TRIM(AC.FORM_EMAIL_UPDATE_CONTACT_KEY)   as   FORM_EMAIL_UPDATED_EAB_ID ,  TRIM(AC.Form_Student_Addr)   as   FORM_STUDENT_ADDR ,  TRIM(AC.Form_Student_City)   as   FORM_STUDENT_CITY ,  TRIM(AC.Form_Student_Stateprov)   as   form_student_stateprov ,  TRIM(AC.Form_Student_Post_Code)   as   form_student_post_code ,  TRIM(AC.Form_Student_Country)   as   form_student_country ,  TRIM(AC.Form_Sms_Opt_In)   as   form_sms_opt_in ,  TRIM(AC.Engaged_Inq_Cmpgn_Acsl)   as   engaged_inq_cmpgn_acsl ,  TRIM(AC.Engaged_Reeng_Cmpgn_Acsl)   as   engaged_reeng_cmpgn_acsl ,  TRIM(parent.FIRST_NAME)   as   child_first_name_calc ,  TRIM(parent.LAST_NAME)