select agg.*
from (select distinct calculated_field_3, pd_int.primary_student_id,

case when pd_int.student_type is null then 'Other' 
else coalesce(pcm_stud_type.eab_standard_value,'Unmapped Value')
end student_type_eab,

case when pd_int.current_entry_term is null then 'Fall' 
else coalesce(pcm_curr_entry_term.eab_standard_value,'Unmapped Value')
end entry_term_eab,

case when pd_int.current_entry_year_as_academic_year is null then null
else coalesce(pcm_curr_entry_yr_acad.eab_standard_value,'Unmapped Value')
end entry_year_as_academic_year_eab,

pd_int.campus_visit_count,
pd_int.campus_visit_flag,
case when pd_int.campus_visit_flag is null then null 
else coalesce(pcm_camp_vis.eab_standard_value,'Unmapped Value')
end campus_visit_flag_eab,

substring(pd_int.first_campus_visit_date,0,10) as first_campus_visit_date,
substring(pd_int.campus_visit_date,0,10) as campus_visit_date,
substring(pd_int.most_recent_campus_visit_date,0,10) as most_recent_campus_visit_date

from <[enrollment_services].[Partner Data Interaction]> pd_int

left outer join <[enrollment_services].[Partner Code Mapping]> pcm_stud_type
on (pcm_stud_type.field_name = 'eab_student_type' and pcm_stud_type.partner_value = pd_int.student_type)

left outer join <[enrollment_services].[Partner Code Mapping]> pcm_curr_entry_term
on (pcm_curr_entry_term.field_name = 'eab_entry_term' and pcm_curr_entry_term.partner_value = pd_int.current_entry_term)

left outer join <[enrollment_services].[Partner Code Mapping]> pcm_curr_entry_yr_acad
on (pcm_curr_entry_yr_acad.field_name = 'eab_entry_year_academic' and pcm_curr_entry_yr_acad.partner_value = pd_int.current_entry_year_as_academic_year)

left outer join <[enrollment_services].[Partner Code Mapping]> pcm_camp_vis
on (pcm_camp_vis.field_name = 'eab_campus_visit_ind' and pcm_camp_vis.partner_value = pd_int.campus_visit_flag)
	  ) agg
  where coalesce(agg.calculated_field_3,'') = 'H'
  AND agg.primary_student_id NOT IN ('659639850', '813705685', '135722493', '611850754', '550236554', '975378693')

